import { describe, it, expect } from "vitest";

// §18 (2026-10-07) — every autogenerated SKU is a NEW product; NNN is never
// shared across ASINs.
//
// Replaces same-product-collision.test.ts, which pinned the opposite rule:
// two new-product rows claiming one (brand, NNN) was the documented
// "same product, different ASIN" case, surfaced as a per-group
// "Same product listed under N ASINs?" resolution with a same-TTL group
// requirement, and resolved either by sharing the NNN (reuse_ok server-side)
// or by bumping the later rows. The inference was wrong every time in
// practice — equal TTLs are two products that derived the same 3 chars.
//
// The live pair that rule cited, B0D97XHDXR + B091ZGHPDR (both LEM STD 003),
// is kept here as the fixture: under the new rule it is an error, not a group.
import { validateRow } from "./offer-add-preview-dialog";

const lemRow = (asin: string, registry: any[] = []) => ({
  asin,
  outcome: {
    kind: "preview" as const, asin, reused: false,
    sku: `LEM-HOM-${asin.slice(-3)}-STD-001`,
    brandCode: "LEM", registry, proposedNnn: 1, proposedTtl: "STD",
  } as any,
});

const A = "B0D97XHDXR", B = "B091ZGHPDR", C = "B000THIRD1";

function run(
  asin: string,
  rows: any[],
  edits: Record<string, { nnnInput: string; ttlForNew: string }>,
) {
  const row = rows.find((r) => r.asin === asin)!;
  return validateRow(edits[asin], row.outcome.sku.split("-"), row.outcome, rows, edits);
}

describe("in-batch: two rows of one brand can never claim one NNN", () => {
  const rows = [lemRow(A), lemRow(B)];

  it("same brand + same NNN + same TTL → error on both rows, no prompt", () => {
    const edits = {
      [A]: { nnnInput: "003", ttlForNew: "STD" },
      [B]: { nnnInput: "003", ttlForNew: "STD" },
    };
    for (const asin of [A, B]) {
      const v = run(asin, rows, edits);
      expect(v.error).toMatch(/already claimed by/);
      expect(v.error).toMatch(/own product number/);
      expect((v as any).resolution).toBeUndefined();
    }
  });

  it("a DIFFERENT TTL does not excuse the shared NNN", () => {
    // Under the old rule a diverging TTL was a correctable inline error
    // inside an otherwise-valid same-product group. Now the clash is on
    // (brand, NNN) alone and TTL has no say in it.
    const edits = {
      [A]: { nnnInput: "003", ttlForNew: "STD" },
      [B]: { nnnInput: "003", ttlForNew: "XYZ" },
    };
    expect(run(A, rows, edits).error).toMatch(/already claimed by/);
    expect(run(B, rows, edits).error).toMatch(/already claimed by/);
  });

  it("three rows on one NNN all error — no group forms", () => {
    const three = [lemRow(A), lemRow(B), lemRow(C)];
    const edits = {
      [A]: { nnnInput: "003", ttlForNew: "STD" },
      [B]: { nnnInput: "003", ttlForNew: "STD" },
      [C]: { nnnInput: "003", ttlForNew: "STD" },
    };
    for (const asin of [A, B, C]) {
      expect(run(asin, three, edits).error).toMatch(/already claimed by/);
    }
  });

  it("distinct NNNs in the same brand validate clean", () => {
    const edits = {
      [A]: { nnnInput: "003", ttlForNew: "STD" },
      [B]: { nnnInput: "004", ttlForNew: "STD" },
    };
    for (const asin of [A, B]) {
      const v = run(asin, rows, edits);
      expect(v.error).toBeUndefined();
      expect(v.finalSku).toMatch(/^LEM-HOM-\w{3}-STD-00[34]$/);
    }
  });

  it("same NNN under DIFFERENT brands is fine — NNN is unique per brand", () => {
    const other = {
      asin: C,
      outcome: {
        kind: "preview" as const, asin: C, reused: false,
        sku: "KAR-HOM-ID1-STD-001", brandCode: "KAR", registry: [],
        proposedNnn: 1, proposedTtl: "STD",
      } as any,
    };
    const mixed = [lemRow(A), other];
    const edits = {
      [A]: { nnnInput: "003", ttlForNew: "STD" },
      [C]: { nnnInput: "003", ttlForNew: "STD" },
    };
    expect(run(A, mixed, edits).error).toBeUndefined();
    expect(run(C, mixed, edits).error).toBeUndefined();
  });

  it("byte-identical final SKU keeps its own X-suffix error", () => {
    // Same ASIN tail → same AS3 → identical SKU. That is a duplicate offer on
    // ONE SKU, which is X-suffix territory and never auto-resolves. It must
    // not be swallowed by the generic "already claimed" message.
    const twin = [lemRow(A), { ...lemRow(B), outcome: { ...lemRow(B).outcome, sku: lemRow(A).outcome.sku } }];
    const edits = {
      [A]: { nnnInput: "003", ttlForNew: "STD" },
      [B]: { nnnInput: "003", ttlForNew: "STD" },
    };
    expect(run(A, twin, edits).error).toMatch(/byte-identical/);
    expect(run(A, twin, edits).error).toMatch(/X variant suffix/);
  });
});

describe("hand-typed NNN that is already registered", () => {
  const registry = [
    { nnn: 3, ttl: "STD", productName: "Spooky Town Display Platform", firstAsin: "B0D97XHDXR" },
  ];

  it("is an error, not a 'reusing product' row", () => {
    const rows = [lemRow(B, registry)];
    const edits = { [B]: { nnnInput: "003", ttlForNew: "STD" } };
    const v = run(B, rows, edits);
    expect(v.error).toMatch(/already belongs to B0D97XHDXR/);
    expect(v.error).toMatch(/own product number/);
    // The reuse affordances are gone with the rule.
    expect((v as any).classification).toBeUndefined();
    expect((v as any).existingRow).toBeUndefined();
  });

  it("errors even when the operator's TTL matches the registered one", () => {
    // Matching TTL was the whole trigger for reuse. It no longer is.
    const rows = [lemRow(B, registry)];
    expect(run(B, rows, { [B]: { nnnInput: "003", ttlForNew: "STD" } }).error).toBeDefined();
    expect(run(B, rows, { [B]: { nnnInput: "003", ttlForNew: "ZZZ" } }).error).toBeDefined();
  });

  it("a free NNN in a brand that has registry rows still validates clean", () => {
    const rows = [lemRow(B, registry)];
    const v = run(B, rows, { [B]: { nnnInput: "004", ttlForNew: "STD" } });
    expect(v.error).toBeUndefined();
    expect(v.finalSku).toBe("LEM-HOM-D4-STD-004".replace("D4", B.slice(-3)));
  });
});
